-- ============================================================
-- サンプルデータ投入スクリプト（F-REP-005 契約者削除一覧）
-- 用途: 先行開発の委託先が帳票の検索・並べ替え機能を動作確認するための正常データ
-- 注意: 本番環境へ適用してはならない
-- 注意: 冪等（IF NOT EXISTS）で設計する。複数回実行しても件数は増えない
-- 前提: db/migrations/V001__InitialSchema.sql と db/testdata/DevelopmentData.sql の投入が完了していること
-- ============================================================
USE [UnifiedAccount];
GO

SET NOCOUNT ON;
SET QUOTED_IDENTIFIER ON;
SET ANSI_NULLS ON;

BEGIN TRANSACTION;

-- ============================================================
-- TR_ContractMasterDeleteLogs (契約者削除ログ) 20件
-- 本ジョブは CompanyCode と PersonalCode の昇順で読み込むため、
-- 並べ替えが効いていることを確認できるよう INSERT の順序は昇順にしない。
-- ============================================================
INSERT INTO [dbo].[TR_ContractMasterDeleteLogs]
    ([JobExecutionId], [CompanyCode], [PersonalCode], [DepositorName], [ContractorName],
     [BankCode], [BranchCode], [AccountType], [AccountNumber], [DeletionDate])
SELECT src.*
FROM (VALUES
    (N'KOZ840-20260827-0001', N'000002', N'000002000005', N'テスト　ゴロウ', N'テスト　ゴロウ',
     N'0005', N'201', N'1', N'2000005000', CAST('2026-08-26' AS date)),
    (N'KOZ840-20260827-0001', N'000001', N'000001000103', N'テスト　タロウ', N'テスト　タロウ',
     N'0543', N'001', N'1', N'1000103000', CAST('2026-08-25' AS date)),
