     N'0543', N'101', N'1', N'1000101000', CAST('2026-08-25' AS date)),
    (N'KOZ840-20260827-0001', N'000002', N'000002000001', N'サンプル　ジロウ', N'サンプル　ジロウ',
     N'0001', N'001', N'1', N'2000001000', CAST('2026-08-26' AS date)),
    (N'KOZ840-20260827-0001', N'000001', N'000001000105', N'テスト　サブロウ', N'テスト　サブロウ',
     N'3054', N'001', N'1', N'1000105000', CAST('2026-08-25' AS date)),
    (N'KOZ840-20260827-0001', N'000003', N'000003000001', N'サンプル　シロウ', N'サンプル　シロウ',
     N'1234', N'001', N'1', N'3000001000', CAST('2026-08-27' AS date)),
    (N'KOZ840-20260827-0001', N'000001', N'000001000102', N'テスト　ハナコ', N'テスト　ハナコ',
     N'0543', N'201', N'2', N'1000102000', CAST('2026-08-25' AS date)),
    (N'KOZ840-20260827-0001', N'000002', N'000002000003', N'サンプル　ロクロウ', N'サンプル　ロクロウ',
     N'0009', N'001', N'1', N'2000003000', CAST('2026-08-26' AS date)),
    (N'KOZ840-20260827-0001', N'000001', N'000001000107', N'テスト　ナナコ', N'テスト　ナナコ',
     N'1025', N'001', N'1', N'1000107000', CAST('2026-08-26' AS date)),
    (N'KOZ840-20260827-0001', N'000002', N'000002000002', N'サンプル　シチロウ', N'サンプル　シチロウ',
     N'0005', N'001', N'1', N'2000002000', CAST('2026-08-26' AS date)),
    (N'KOZ840-20260827-0001', N'000001', N'000001000104', N'テスト　ヨシコ', N'テスト　ヨシコ',
     N'3054', N'002', N'1', N'1000104000', CAST('2026-08-25' AS date)),
    (N'KOZ840-20260827-0001', N'000003', N'000003000003', N'サンプル　ハチロウ', N'サンプル　ハチロウ',
     N'9900', N'001', N'1', N'3000003000', CAST('2026-08-27' AS date)),
    (N'KOZ840-20260827-0001', N'000001', N'000001000108', N'テスト　ヤエコ', N'テスト　ヤエコ',
     N'1025', N'002', N'2', N'1000108000', CAST('2026-08-26' AS date)),
    (N'KOZ840-20260827-0001', N'000002', N'000002000004', N'サンプル　クロウ', N'サンプル　クロウ',
     N'0001', N'101', N'1', N'2000004000', CAST('2026-08-26' AS date)),
    (N'KOZ840-20260827-0001', N'000001', N'000001000106', N'テスト　ムツコ', N'テスト　ムツコ',
