) AS src (JobExecutionId, CompanyCode, PersonalCode, DepositorName, ContractorName,
          BankCode, BranchCode, AccountType, AccountNumber, DeletionDate)
WHERE NOT EXISTS (
    SELECT 1 FROM [dbo].[TR_ContractMasterDeleteLogs] d
    WHERE d.JobExecutionId = src.JobExecutionId
      AND d.CompanyCode = src.CompanyCode
      AND d.PersonalCode = src.PersonalCode
);

COMMIT TRANSACTION;
PRINT 'Sample-F-REP-005 投入完了';
